<?php defined('BASEPATH') OR exit('No direct script access allowed');class Erp extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Erp_model','erp');}function resource($type,$id=NULL){if(!in_array($type,array('products','warehouses','suppliers'),TRUE))return $this->fail('NOT_FOUND','Resource not found',404);$m=$this->input->method(TRUE);if($m==='GET'){if($id){$r=$this->erp->one($type,$id,$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Record not found',404);}return $this->respond($this->erp->list_resource($type,$this->c['organizationId'],array('category'=>$this->input->get('category'),'is_active'=>$this->input->get('active'))));}if($m==='DELETE')return $this->erp->remove($type,$id,$this->c['organizationId'])?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Record not found',404);$d=$this->body();$required=array('products'=>array('sku','name','priceCents','costCents'),'warehouses'=>array('name','code'),'suppliers'=>array('name'));if(!$id)foreach($required[$type] as $f)if(!isset($d[$f])||$d[$f]==='')return $this->fail('VALIDATION_ERROR',$f.' required',422);$r=$this->erp->save($type,$id,$this->c['organizationId'],$this->c['sub'],$d);return $r?$this->respond($r,$id?200:201):$this->fail('NOT_FOUND','Record not found',404);}function inventory(){return $this->respond($this->erp->inventory($this->c['organizationId']));}function movements(){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(!isset($d['productId'],$d['warehouseId'],$d['kind'],$d['quantity'])||!in_array($d['kind'],array('receipt','sale','adjustment','transfer_in','transfer_out','initial'),TRUE)||$d['quantity']==0)return $this->fail('VALIDATION_ERROR','Invalid movement',422);$r=$this->erp->movement($this->c['organizationId'],$this->c['sub'],$d);return $r?$this->respond($r,201):$this->fail('VALIDATION_ERROR','Product or warehouse not found',422);}return $this->respond($this->erp->list_resource('movements',$this->c['organizationId'],array('product_id'=>$this->input->get('productId'),'warehouse_id'=>$this->input->get('warehouseId'),'kind'=>$this->input->get('kind'))));}function orders($kind,$id=NULL){if(!in_array($kind,array('purchase','sales'),TRUE))return $this->fail('NOT_FOUND','Order type not found',404);$m=$this->input->method(TRUE);if($m==='GET'){if($id){$r=$this->erp->order($kind,$id,$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Order not found',404);}return $this->respond($this->erp->orders($kind,$this->c['organizationId'],$this->input->get('status')));}if($m==='DELETE')return $this->erp->delete_order($kind,$id,$this->c['organizationId'])?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Order not found',404);$d=$this->body();if((!$id&&$kind==='purchase'&&empty($d['supplierId']))||(!$id&&!isset($d['items']))||(isset($d['items'])&&(!is_array($d['items'])||count($d['items'])>200)))return $this->fail('VALIDATION_ERROR','Invalid order',422);foreach($d['items']??array() as $x)if(empty($x['productId'])||($x['qty']??0)<1||($x['unitPriceCents']??-1)<0||!$this->erp->one('products',$x['productId'],$this->c['organizationId']))return $this->fail('VALIDATION_ERROR','Invalid product line',422);if($kind==='purchase'&&!$this->erp->one('suppliers',$d['supplierId']??$this->erp->order($kind,$id,$this->c['organizationId'])['supplierId'],$this->c['organizationId']))return $this->fail('VALIDATION_ERROR','Supplier not found',422);$r=$this->erp->save_order($kind,$id,$this->c['organizationId'],$d);return $r?$this->respond($r,$id?200:201):$this->fail('NOT_FOUND','Order not found',404);}function receive($id){$r=$this->erp->receive($id,$this->c['organizationId'],$this->c['sub']);return $r?$this->respond($r):$this->fail($r===FALSE?'VALIDATION_ERROR':'NOT_FOUND',$r===FALSE?'A default warehouse is required':'Purchase order not found or cannot be received',$r===FALSE?422:404);}function fulfill($id){$r=$this->erp->fulfill($id,$this->c['organizationId'],$this->c['sub']);return $r?$this->respond($r):$this->fail($r===FALSE?'VALIDATION_ERROR':'NOT_FOUND',$r===FALSE?'A default warehouse is required':'Sales order not found or cannot be fulfilled',$r===FALSE?422:404);}function from_deal($id){$r=$this->erp->from_deal($id,$this->c['organizationId']);return $r?$this->respond($r,201):$this->fail('VALIDATION_ERROR','A closed-won CRM deal is required',422);}function dashboard(){return $this->respond($this->erp->rollup($this->c['organizationId']));}}
